private Grid BuildDashboard(){var root=new Grid{Margin=new Thickness(0,4,0,0)};root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(320)});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(286)});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});var top=new Grid();top.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.05,GridUnitType.Star)});top.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(.92,GridUnitType.Star)});top.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.05,GridUnitType.Star)});var current=MakeCard((Brush)FindResource("AccentBrush"));_currentCard=current;var cg=new Grid();cg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(34)});cg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});cg.Children.Add(Header("♢  "+(IsGerman?"AKTUELL INSTALLIERT":"CURRENTLY INSTALLED"),(Brush)FindResource("AccentBrush")));var cs=new StackPanel{Margin=new Thickness(0,8,0,0)};Grid.SetRow(cs,1);_currentValue=new TextBlock{Text="—",FontSize=39,FontWeight=FontWeights.SemiBold};_currentDetails=new TextBlock{FontSize=13,Foreground=(Brush)FindResource("SecondaryBrush"),LineHeight=24,Margin=new Thickness(0,18,0,0)};cs.Children.Add(_currentValue);cs.Children.Add(new Border{Height=1,Background=(Brush)FindResource("BorderBrush"),Margin=new Thickness(0,14,0,4)});cs.Children.Add(_currentDetails);cg.Children.Add(cs);current.Child=cg;Grid.SetColumn(current,0);top.Children.Add(current);var logo=MakeCard((Brush)FindResource("AccentBrush"));logo.Padding=new Thickness(12);logo.Child=new Image{Source=LoadLogo(),Stretch=Stretch.Uniform};Grid.SetColumn(logo,1);top.Children.Add(logo);var ts=MakeCard((Brush)FindResource("GoldBrush"));var tg=new Grid();tg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(34)});tg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});tg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(50)});tg.Children.Add(Header("◉  TEAMSpeak 3 STATUS",(Brush)FindResource("AccentBrush")));var tsStack=new StackPanel{Margin=new Thickness(0,8,0,0),HorizontalAlignment=HorizontalAlignment.Center};Grid.SetRow(tsStack,1);_tsStatus=new TextBlock{Name="TsStatus",Text="—",FontSize=28,FontWeight=FontWeights.SemiBold,Foreground=(Brush)FindResource("GoldBrush"),HorizontalAlignment=HorizontalAlignment.Center};_tsDescription=new TextBlock{Name="TsDescription",FontSize=14,Foreground=(Brush)FindResource("SecondaryBrush"),TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center,Margin=new Thickness(0,10,0,0)};tsStack.Children.Add(_tsStatus);tsStack.Children.Add(_tsDescription);tg.Children.Add(tsStack);_tsClose=new Button{Content="◉  TS3 schließen",Visibility=Visibility.Collapsed,Style=(Style)FindResource("TileButtonStyle"),Foreground=(Brush)FindResource("GoldBrush"),BorderBrush=(Brush)FindResource("GoldBrush")};_tsClose.Click+=(_,_)=>CloseTeamSpeak();Grid.SetRow(_tsClose,2);tg.Children.Add(_tsClose);ts.Child=tg;Grid.SetColumn(ts,2);top.Children.Add(ts);Grid.SetRow(top,0);root.Children.Add(top);var actions=new Grid{Margin=new Thickness(0,8,0,8)};for(var i=0;i<3;i++)actions.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});AddTile(actions,0,"⇄","YACA WECHSELN",IsGerman?"Version auswählen\nund wechseln":"Select a version\nand switch",(Brush)FindResource("AccentBrush"),ShowSwitchPage);AddTile(actions,1,"＋","BACKUP ERSTELLEN",IsGerman?"Aktuelle Version\nsichern":"Save current version",(Brush)FindResource("GoldBrush"),CreateBackupFromDashboard);AddTile(actions,2,"☁","YACA UPDATER",IsGerman?"Neueste DLL prüfen\nund herunterladen":"Check and download\nlatest DLL",(Brush)FindResource("AccentBrush"),()=>ShowComingSoon(),true);Grid.SetRow(actions,1);root.Children.Add(actions);var lower=new Grid();lower.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(.98,GridUnitType.Star)});lower.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.02,GridUnitType.Star)});var backup=MakeCard((Brush)FindResource("BorderBrush"));_backupCard=backup;var bg=new Grid();bg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(34)});bg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});bg.Children.Add(Header("▱  "+(IsGerman?"LETZTES BACKUP":"LATEST BACKUP"),(Brush)FindResource("AccentBrush")));_backupSummary=new TextBlock{FontSize=14,Foreground=(Brush)FindResource("ForegroundBrush"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,0)};Grid.SetRow(_backupSummary,1);bg.Children.Add(_backupSummary);backup.Child=bg;Grid.SetColumn(backup,0);lower.Children.Add(backup);var versions=MakeCard((Brush)FindResource("BorderBrush"));var vg=new Grid();vg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(34)});vg.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});vg.Children.Add(Header("◉  "+(IsGerman?"VERFÜGBARE YACA-VERSIONEN":"AVAILABLE YACA VERSIONS"),(Brush)FindResource("AccentBrush")));_versionList=new StackPanel{Margin=new Thickness(0,8,0,0)};Grid.SetRow(_versionList,1);vg.Children.Add(_versionList);versions.Child=vg;Grid.SetColumn(versions,1);lower.Children.Add(versions);Grid.SetRow(lower,2);root.Children.Add(lower);return root;}
private static TextBlock Header(string text,Brush accent)=>new(){Text=text,Foreground=accent,FontSize=16,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center};private Border MakeCard(Brush border)=>new(){Style=(Style)FindResource("CardStyle"),BorderBrush=border,BorderThickness=new Thickness(1)};private static BitmapImage LoadLogo()=>new(new Uri("pack://application:,,,/YacaPluginSwitcher;component/Assets/yaca_logo.png"));
private void AddTile(Grid host,int column,string icon,string title,string subtitle,Brush accent,Action action,bool coming=false){var button=new Button{Style=(Style)FindResource("TileButtonStyle"),BorderBrush=accent,Margin=new Thickness(6)};var panel=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};panel.Children.Add(new TextBlock{Text=icon,FontSize=55,Foreground=accent,HorizontalAlignment=HorizontalAlignment.Center});panel.Children.Add(new TextBlock{Text=title,FontSize=23,FontWeight=FontWeights.SemiBold,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,8,0,4)});panel.Children.Add(new TextBlock{Text=subtitle,FontSize=14,Foreground=(Brush)FindResource("SecondaryBrush"),TextAlignment=TextAlignment.Center});if(coming){var tileGrid=new Grid();tileGrid.Children.Add(panel);tileGrid.Children.Add(new Border{HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top,Background=(Brush)FindResource("NavSelectedBrush"),CornerRadius=new CornerRadius(5),Padding=new Thickness(11,5,11,5),Margin=new Thickness(0,-2,-2,0),Child=new TextBlock{Text=IsGerman?"BALD\nVERFÜGBAR":"COMING\nSOON",Foreground=Brushes.White,FontSize=11,FontWeight=FontWeights.SemiBold,TextAlignment=TextAlignment.Center}});button.Content=tileGrid;}else button.Content=panel;button.Click+=(_,_)=>action();Grid.SetColumn(button,column);host.Children.Add(button);}
private void RefreshHome(bool announce=false){if(_activePage!="home")return;try{_plugins.Clear();_plugins.AddRange(GetDistinctPlugins());var notice=announce?GetNewPluginNotice(_plugins):null;if(!_pluginBaselineInitialized)SetPluginBaseline(_plugins);var current=_service.DetectCurrent();_currentValue!.Text=current?.DisplayName??(File.Exists(_service.TargetFile)?Texts.UnknownInvalid:Texts.NotInstalled);_currentValue.Foreground=current is null?(Brush)FindResource("WarningBrush"):(Brush)FindResource("ForegroundBrush");_currentDetails!.Text=current is null?"":$"Datei     {Path.GetFileName(current.FilePath)}\nGröße     {current.FileSize/1024d/1024d:0.00} MB\nSHA-256   {current.Sha256[..Math.Min(12,current.Sha256.Length)]}…";if(announce)FlashElement(_currentCard);var running=TeamSpeakDetector.IsRunning();_tsStatus!.Text=running?(IsGerman?"GESTARTET":"RUNNING"):(IsGerman?"NICHT GESTARTET":"NOT RUNNING");_tsStatus.Foreground=running?(Brush)FindResource("ErrorBrush"):(Brush)FindResource("GoldBrush");_tsDescription!.Text=running?(IsGerman?"TeamSpeak 3 ist aktiv. Für einen sicheren Wechsel bitte zuerst schließen.":"TeamSpeak 3 is active. Close it before switching."):(IsGerman?"TeamSpeak 3 ist nicht aktiv.\nWechsel jederzeit möglich.":"TeamSpeak 3 is not active.\nSwitching is ready.");_tsClose!.Visibility=running?Visibility.Visible:Visibility.Collapsed;var backup=_service.Backups.ListBackups().FirstOrDefault();_backupSummary!.Text=backup is null?Texts.NoBackups:$"{backup.Timestamp:dd.MM.yyyy HH:mm}\n{backup.DisplayName}  •  {backup.FileSize/1024d/1024d:0.00} MB\nDatei  {backup.FileName}";_versionList!.Children.Clear();for(var i=0;i<Math.Min(3,_plugins.Count);i++){var p=_plugins[i];var row=new DockPanel{Margin=new Thickness(0,0,0,10)};row.Children.Add(new TextBlock{Text=p.DisplayName,FontSize=14});if(current?.Sha256.Equals(p.Sha256,StringComparison.OrdinalIgnoreCase)==true){var badge=new Border{Background=(Brush)FindResource("SuccessBrush"),CornerRadius=new CornerRadius(4),Padding=new Thickness(9,3,9,3),Child=new TextBlock{Text=IsGerman?"AKTUELL":"CURRENT",Foreground=Brushes.Black,FontSize=11,FontWeight=FontWeights.Bold}};DockPanel.SetDock(badge,Dock.Right);row.Children.Add(badge);}_versionList!.Children.Add(row);}var more=new TextBlock{Text=$"{_plugins.Count.ToString(CultureInfo.InvariantCulture)} Version(en) verfügbar   ›",Foreground=(Brush)FindResource("AccentBrush"),FontSize=14,Margin=new Thickness(0,6,0,0)};more.MouseLeftButtonUp+=(_,_)=>ShowSwitchPage();_versionList.Children.Add(more);StatusText.Text=string.IsNullOrWhiteSpace(notice)?(running?Texts.TeamspeakRunning:Texts.TeamspeakStopped):notice;}catch(Exception ex){_service.Logger.Error($"Dashboard refresh failed: {ex}");StatusText.Text=Texts.ErrorUnexpected;}}
private List<YacaPluginInfo> GetDistinctPlugins(){var result=new List<YacaPluginInfo>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var p in _service.ScanPlugins())if(seen.Add($"{p.FilePath}|{p.Sha256}"))result.Add(p);return result;}
private string? GetNewPluginNotice(IReadOnlyList<YacaPluginInfo> plugins){var keys=plugins.Select(p=>$"{p.FilePath}|{p.Sha256}").ToHashSet(StringComparer.OrdinalIgnoreCase);if(!_pluginBaselineInitialized){_knownPlugins=keys;_pluginBaselineInitialized=true;return null;}var added=plugins.Where(p=>!_knownPlugins.Contains($"{p.FilePath}|{p.Sha256}")).ToList();_knownPlugins=keys;return added.Count==0?null:string.Format(CultureInfo.CurrentCulture,Texts.NewValidPluginFound,string.Join(", ",added.Select(p=>p.DisplayName)));}
private void SetPluginBaseline(IReadOnlyList<YacaPluginInfo> plugins){_knownPlugins=plugins.Select(p=>$"{p.FilePath}|{p.Sha256}").ToHashSet(StringComparer.OrdinalIgnoreCase);_pluginBaselineInitialized=true;}
private void ShowSwitchPage(string? status=null){_activePage="switch";SetActiveNav("switch");var root=new Grid();root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(54)});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(62)});root.Children.Add(new TextBlock{Text=IsGerman?"YACA wechseln":"Switch YACA",FontSize=24,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center});var list=new StackPanel();var scroll=new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);root.Children.Add(scroll);var current=_service.DetectCurrent();foreach(var p in GetDistinctPlugins()){var active=current?.Sha256.Equals(p.Sha256,StringComparison.OrdinalIgnoreCase)==true;var b=new Button{Style=(Style)FindResource("TileButtonStyle"),BorderBrush=active?(Brush)FindResource("SuccessBrush"):(Brush)FindResource("AccentBrush"),Margin=new Thickness(6),Height=58,HorizontalContentAlignment=HorizontalAlignment.Left,Content=new TextBlock{Text=active?$"{p.DisplayName}   —   {Texts.Active.TrimEnd(':')}":p.DisplayName,FontSize=15,Foreground=active?(Brush)FindResource("SuccessBrush"):(Brush)FindResource("ForegroundBrush")}};b.Click+=(_,_)=>Activate(p);list.Children.Add(b);}_pageStatusBorder=new Border{Background=(Brush)FindResource("SurfaceBrush"),BorderBrush=(Brush)FindResource("BorderBrush"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(8),Margin=new Thickness(6,6,6,0),Padding=new Thickness(14,0,14,0)};_pageStatus=new TextBlock{Text=status??(IsGerman?"Bereit.":"Ready."),FontSize=14,Foreground=(Brush)FindResource("SecondaryBrush"),VerticalAlignment=VerticalAlignment.Center,TextAlignment=TextAlignment.Center};_pageStatusBorder.Child=_pageStatus;Grid.SetRow(_pageStatusBorder,2);root.Children.Add(_pageStatusBorder);PageHost.Content=root;}
private void Activate(YacaPluginInfo plugin){var text=Texts;var current=_service.DetectCurrent();if(current?.Sha256.Equals(plugin.Sha256,StringComparison.OrdinalIgnoreCase)==true){ShowPageStatus(text.AlreadyActiveMessage,false);return;}if(_service.Settings.WarnIfTeamSpeakRunning&&TeamSpeakDetector.IsRunning()&&MessageBox.Show(text.TeamspeakRunningMessage,text.TeamspeakRunningTitle,MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{Mouse.OverrideCursor=Cursors.Wait;_service.Installer.Install(plugin,_service.TargetFile,current,_service.Settings.AutomaticBackup,_service.Settings.MaxBackups);ShowSwitchPage($"{plugin.DisplayName} {text.ActivatedMessage}");}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or InvalidDataException or InvalidOperationException or YacaOperationException){_service.Logger.Error($"YACA switch failed: {ex}");ShowError(Localization.GetErrorMessage(ex,text,text.ErrorUnexpected));}finally{Mouse.OverrideCursor=null;}}
private void CreateBackupFromDashboard(){var text=Texts;if(TeamSpeakDetector.IsRunning()&&_service.Settings.WarnIfTeamSpeakRunning&&MessageBox.Show(text.TeamspeakRunningMessage,text.TeamspeakRunningTitle,MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{var current=_service.DetectCurrent();if(current is null){ShowError(text.NotInstalled);return;}if(_service.Backups.CreateBackup(_service.TargetFile,current) is null){ShowError(text.ErrorUnexpected);return;}_service.Backups.Trim(_service.Settings.MaxBackups);RefreshHome();FlashElement(_backupCard);}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or InvalidDataException or InvalidOperationException){_service.Logger.Error($"Dashboard backup failed: {ex}");ShowError(Localization.GetErrorMessage(ex,text,text.ErrorUnexpected));}}
private void CloseTeamSpeak(){var text=Texts;if(!TeamSpeakDetector.IsRunning()){RefreshHome();return;}if(MessageBox.Show(text.CloseTeamspeakQuestion,text.TeamspeakRunningTitle,MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{Mouse.OverrideCursor=Cursors.Wait;if(!TeamSpeakDetector.TryClose(TimeSpan.FromSeconds(5)))MessageBox.Show(text.CloseTeamspeakFailed,text.TeamspeakRunningTitle,MessageBoxButton.OK,MessageBoxImage.Error);}catch(Exception ex)when(ex is InvalidOperationException or System.ComponentModel.Win32Exception){ShowError(Localization.GetErrorMessage(ex,text,text.CloseTeamspeakFailed));}finally{Mouse.OverrideCursor=null;RefreshHome();}}
private void ShowBackups(){_activePage="backups";SetActiveNav("backups");PageHost.Content=new BackupView(_service,this);}private void ShowConfig(){_activePage="config";SetActiveNav("config");PageHost.Content=new ConfigView(_service,this);}private void ShowInfo(){_activePage="info";SetActiveNav("info");PageHost.Content=new InfoView(_service.Settings.Language);}private void ShowComingSoon(){ShowError(IsGerman?"Der YACA Updater wird in einer späteren Version verfügbar sein.":"The YACA Updater will be available in a future version.");}internal void ReturnHome()=>ShowHome();
private void RefreshActivePage(bool announce){if(_activePage=="home")RefreshHome(announce);else if(_activePage=="switch")ShowSwitchPage();else if(_activePage=="backups")PageHost.Content=new BackupView(_service,this);else if(_activePage=="config")PageHost.Content=new ConfigView(_service,this);}
private void ShowPageStatus(string message,bool success){if(_pageStatus is null){ShowSwitchPage(message);return;}_pageStatus.Text=message;_pageStatus.Foreground=(Brush)FindResource(success?"SuccessBrush":"ForegroundBrush");_pageStatusBorder!.BorderBrush=(Brush)FindResource(success?"SuccessBrush":"BorderBrush");}
private void FlashElement(Border? element){if(element is null)return;_flashTimer?.Stop();var original=element.BorderBrush;element.BorderBrush=(Brush)FindResource("GoldBrush");_flashTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)};_flashTimer.Tick+=(_,_)=>{element.BorderBrush=original;_flashTimer!.Stop();};_flashTimer.Start();}
private void ShowError(string message){if(_activePage!="home"&&_pageStatus is not null){ShowPageStatus(message,false);return;}MessageBox.Show(message,Texts.ErrorTitle,MessageBoxButton.OK,MessageBoxImage.Error);}
private void Minimize_Click(object sender,RoutedEventArgs e)=>WindowState=WindowState.Minimized;private void Maximize_Click(object sender,RoutedEventArgs e)=>WindowState=WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;private void Close_Click(object sender,RoutedEventArgs e)=>Close();
}